let ranges = 100;

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(0);
}

function draw() {
  background(0);
  noFill();
  strokeWeight(2);

  for (let i = 0; i < ranges; i++) {
    let paint = map(i, 0, ranges, 0, 255);
    stroke(paint);

    beginShape();
    for (let x = -10; x < width + 11; x += 20) {
      let n = noise(x * 0.001, i * 0.01, frameCount * 0.02);
      let y = map(n, 0, 1, 0, height);
      vertex(x, y);
    }
    endShape();
  }
}
